package thaumcraft.test;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.util.ProblemReporter;
import thaumcraft.alchemy.*;
import thaumcraft.essentia.*;
import thaumcraft.content.SimpleContent;
import thaumcraft.mirrors.MirrorEssence;
import thaumcraft.research.*;
public final class BookCompletionProbe {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public static void run(ServerPlayer p){var l=p.level();var at=p.blockPosition().east(2);for(var block:List.of(AlchemyContent.JAR.get(),AlchemyContent.VOID_JAR.get())){l.setBlockAndUpdate(at,block.defaultBlockState());var jar=(AlchemyMachine)l.getBlockEntity(at);p.setItemInHand(InteractionHand.MAIN_HAND,AlchemyContent.filled(AlchemyContent.PHIAL.get(),"ignis",10));check(jar.phial(p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS&&jar.total()==10,"Open jar rejects native phial");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(EssentiaContent.LABEL.get()));check(jar.label(p,InteractionHand.MAIN_HAND,Direction.NORTH)==InteractionResult.SUCCESS,"Label setup failed");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(SimpleContent.ITEMS.get("jar_brace").get(),2));check(jar.brace(p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS&&jar.braced()&&p.getMainHandItem().getCount()==1,"Brace not paid/applied");check(jar.brace(p,InteractionHand.MAIN_HAND)==InteractionResult.FAIL&&p.getMainHandItem().getCount()==1,"Duplicate brace consumes items");for(var phial:List.of(new ItemStack(AlchemyContent.PHIAL.get()),AlchemyContent.filled(AlchemyContent.PHIAL.get(),"ignis",10))){p.setItemInHand(InteractionHand.MAIN_HAND,phial);check(jar.phial(p,InteractionHand.MAIN_HAND)==InteractionResult.FAIL&&jar.total()==10&&phial.getCount()==1,"Braced jar transferred through phial");}check(!MirrorEssence.source(jar)&&!MirrorEssence.drain(l,at,"ignis")&&jar.total()==10,"Braced jar leaks to remote extraction");check(jar.insert("ignis",Direction.UP,false)&&jar.extract("ignis",Direction.UP,false)&&jar.total()==10,"Brace blocked tube transport");var tag=jar.saveWithoutMetadata(l.registryAccess());var copy=new AlchemyMachine(at,block.defaultBlockState());copy.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));check(copy.braced()&&copy.total()==10&&copy.filter().equals("ignis"),"Brace save/load lost state");var drops=Block.getDrops(block.defaultBlockState(),l,at,jar);check(drops.size()==2&&drops.stream().anyMatch(s->s.is(SimpleContent.ITEMS.get("jar_brace").get())&&s.getCount()==1),"Brace not returned once on native block loot");var item=drops.stream().filter(s->s.is(block.asItem())).findFirst().orElseThrow();check(AlchemyContent.amount(item)==10&&AlchemyContent.aspect(item).equals("ignis")&&item.getOrDefault(EssentiaContent.FILTER.get(),"").equals("ignis"),"Jar drop lost essence/filter");var restored=new AlchemyMachine(at,block.defaultBlockState());restored.placeContents(item);check(!restored.braced()&&restored.total()==10&&restored.filter().equals("ignis"),"Collected jar retains brace or loses contents");tag.remove("jar_braced");copy.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));check(!copy.braced()&&copy.total()==10,"Legacy jar incorrectly sealed");l.removeBlock(at,false);}thaumcraft.Thaumcraft.LOGGER.info("BOOK70_BRACE_OK: normal/void jars, payment, phials, remote extraction, tubes, save/load, native drops, legacy state");var views=ResearchCatalog.load("recipe_views.json").getAsJsonObject();for(var e:ResearchCatalog.ENTRIES){for(var stage:e.stages())for(var ref:stage.recipes())check(views.has(ref),"Missing book diagram "+ref);for(var a:e.addenda())for(var ref:a.recipes())check(views.has(ref),"Missing addendum diagram "+ref);}for(var c:List.of("white","orange","magenta","light_blue","yellow","lime","pink","gray","light_gray","cyan","purple","blue","brown","green","red","black"))check(l.recipeAccess().getRecipes().stream().anyMatch(h->h.id().identifier().toString().equals("thaumcraft:arcane/banner_"+c)),"Native banner recipe missing "+c);for(var name:List.of("amulet_mundane","ring_mundane","girdle_mundane","amulet_fancy","ring_fancy","girdle_fancy")){check(l.recipeAccess().getRecipes().stream().anyMatch(h->h.id().identifier().toString().equals("thaumcraft:"+name)),"Missing basic accessory recipe "+name);check(net.minecraft.core.registries.BuiltInRegistries.ITEM.containsKey(net.minecraft.resources.Identifier.parse("thaumcraft:"+name)),"Missing native accessory item "+name);}thaumcraft.Thaumcraft.LOGGER.info("BOOK70_BASIC_ACCESSORIES_OK: original six basic accessories; advanced recipes stay in their research topics");thaumcraft.Thaumcraft.LOGGER.info("BOOK70_DIAGRAMS_OK: no unresolved original references; 16 native banner recipes");}
}
